WITH exploded AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(discounts) e AS tier_value) SELECT currency, DATE_TRUNC('WEEK', effective_from) AS week_start, ROUND(AVG(tier_value), 2) AS avg_tier_value, AVG(tier_value) FILTER (WHERE currency = 'USD') AS usd_avg_tier_value, COUNT(*) AS event_count, SUM(CASE WHEN currency = 'USD' THEN tier_value ELSE 0 END) AS usd_tier_value FROM exploded GROUP BY CUBE (currency, DATE_TRUNC('WEEK', effective_from)) ORDER BY usd_tier_value DESC
